from math import ceil
def solution(n, stations, w):
    answer = 0
    ap = 1
    for st in stations:
        if st - w > ap:
            aparts = st - w - ap
            answer += ceil(aparts / (2 * w + 1))
        ap = st + w + 1
    if ap <= n:
        aparts = n - ap + 1
        answer += ceil(aparts / (2 * w + 1))
    return answer

def solution(operations):
    que = []
    for o in operations:
        c, i = o.split()
        if c == "I":
            que.append(int(i))
        elif not que:
            continue
        elif i == "-1":
            que.remove(min(que))
        else:
            que.remove(max(que))
    if que:
        return [max(que), min(que)]
    return [0, 0]

def solution(n, computers):
    answer = 0
    connected = [False] * n

    def net(c):
        connected[c] = True
        for i in range(n):
            if i != c and not connected[i] and computers[c][i]:
                net(i)

    for i in range(n):
        if connected[i]:
            continue
        net(i)
        answer += 1
    return answer

def solution(n, works):
    if sum(works) <= n:
            return 0
    works.sort(reverse=True)
    while n and sum(works):
        i = next((i for i in range(len(works)) if works[i] < works[0]), None)
        if i:
            minus = works[i - 1] - works[i]
            while minus * i > n:
                minus -= 1
        else:   # 똑같이 남은 경우
            i = len(works)
            minus = n // i

        if minus != 0: # 팍팍 깜
            n -= minus * i
            works[:i] = [w - minus for w in works[:i]]

        else:
            for i in range(n):
                works[i] -= 1
            n = 0
    return sum(w ** 2 for w in works)
